-- Email/password sign-in (Logto-only users keep a null hash).
alter table app_users add column password_hash varchar(100);

-- Schemas generated by ddl-auto pinned the role enum in a CHECK constraint, which would reject SUPER_ADMIN.
alter table app_user_roles drop constraint if exists app_user_roles_role_check;

-- Users that own refresh tokens are deleted by the database, so the user module never touches auth tables.
do $$
declare
    fk record;
begin
    for fk in select conname from pg_constraint where conrelid = 'refresh_tokens'::regclass and contype = 'f' loop
        execute format('alter table refresh_tokens drop constraint %I', fk.conname);
    end loop;
end $$;
alter table refresh_tokens
    add constraint refresh_tokens_user_id_fkey foreign key (user_id) references app_users (id) on delete cascade;

create table loans (
    id             uuid primary key,
    applicant_id   uuid                        not null references app_users (id),
    amount         numeric(15, 2)              not null check (amount > 0),
    term_months    integer                     not null check (term_months between 1 and 120),
    status         varchar(20)                 not null,
    review_comment varchar(500),
    reviewed_by    uuid references app_users (id),
    reviewed_at    timestamp(6) with time zone,
    version        bigint                      not null default 0,
    created_at     timestamp(6) with time zone not null,
    updated_at     timestamp(6) with time zone not null
);

create index idx_loans_applicant on loans (applicant_id, created_at desc);
create index idx_loans_status on loans (status, created_at desc);

-- Audit trail written in the same transaction as each approval or rejection.
create table loan_reviews (
    id          uuid primary key,
    loan_id     uuid                        not null references loans (id),
    reviewer_id uuid                        not null references app_users (id),
    decision    varchar(20)                 not null,
    comment     varchar(500),
    created_at  timestamp(6) with time zone not null,
    updated_at  timestamp(6) with time zone not null
);

create index idx_loan_reviews_loan on loan_reviews (loan_id);
